  first [ lazymatch goal with |- L5.u64_at _ _ _ r => lazymatch goal with H : L5.u64_at _ _ (sp - 8) _ |- _ => rewrite G1, (L5.unsigned_lit r) in H by (clear - Hr; lia); exact H end end ].

